contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We keep a small helper to call Put and Collect and observe public getters.
    // Single public function per constraints.
    function run(uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for put");
        // Record contract balance and holder balance before Put
        uint beforeContract = address(c).balance;
        // Acc is public mapping; getter signature: function Acc(address) returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeHolder) = c.Acc(address(this));

        // Call Put sending Ether putAmount
        c.Put{value: putAmount}(block.timestamp + 1);

        // After Put: contract balance must increase by putAmount
        uint afterContract = address(c).balance;
        (uint afterUnlock, uint afterHolder) = c.Acc(address(this));

        // Now try Collect for collectAmount and observe whether it reverts
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalContract = address(c).balance;
        (uint finalUnlock, uint finalHolder) = c.Acc(address(this));

        // General rule asserted:
        // 1) After Put, contract balance increased by putAmount and recorded holder balance increased by at least putAmount.
        // 2) If Collect succeeded then final contract balance decreased by collectAmount and holder balance decreased by at least collectAmount.
        // 3) If Collect reverted then balances remain unchanged from after Put.
        assert(
            // Part A: Put effects
            afterContract == beforeContract + putAmount
            && afterHolder >= beforeHolder + putAmount
            // Part B/C: relation between Collect outcome and final balances
            && (
                // if reverted: final balances unchanged
                (reverted && finalContract == afterContract && finalHolder == afterHolder)
                // if not reverted: final balances decreased by exactly collectAmount on contract balance and holder balance decreased at least collectAmount
                || (
                    !reverted
                    && afterContract >= collectAmount
                    && finalContract == afterContract - collectAmount
                    && afterHolder >= collectAmount
                    && finalHolder == afterHolder - collectAmount
                )
            )
        );
    }

    // enable receiving Ether so the test contract can hold funds to forward
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that for any sent amount, Put increases address(c).balance by that amount
    // and the public Acc getter for this contract's address reports a holder balance
    // that is >= the previous holder balance plus the sent amount.
    function run(uint putAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to forward");

        // Observe before values
        uint beforeContract = address(c).balance;
        (uint beforeUnlock, uint beforeHolder) = c.Acc(address(this));

        // Call Put forwarding putAmount wei and some unlock time (use block.timestamp to avoid underflow)
        c.Put{value: putAmount}(block.timestamp + 1);

        // Observe after values
        uint afterContract = address(c).balance;
        (uint afterUnlock, uint afterHolder) = c.Acc(address(this));

        // General rule: contract balance increased exactly by putAmount
        // and the recorded holder balance increased by at least putAmount.
        assert(
            afterContract == beforeContract + putAmount
            && afterHolder >= beforeHolder + putAmount
        );
    }

    // allow this test contract to receive Ether so it can forward funds to c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to set up a holder with sufficient balance and unlockTime, then tries Collect.
    // Params:
    //  putAmount: amount of wei to deposit via Put
    //  collectAmount: amount of wei to request via Collect
    //  unlockOffset: seconds added to block.timestamp to set unlockTime (use 0 to set to block.timestamp)
    function run(uint putAmount, uint collectAmount, uint unlockOffset) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to forward");

        // Deposit funds into c for this contract's address
        uint unlockTime = block.timestamp + unlockOffset;
        c.Put{value: putAmount}(unlockTime);

        // If unlockTime is in the future, ensure we only attempt Collect when block.timestamp > stored unlockTime.
        // We cannot advance time here; require that unlockOffset == 0 so stored unlockTime == block.timestamp
        // and then Collect must fail. Therefore require unlockOffset == 0 to make the test reachable and meaningful
        // (we will reason about both outcomes via try/catch).
        // But to allow a successful Collect we need stored unlockTime < block.timestamp; set unlockOffset = 0 and rely
        // on Put implementation which sets unlockTime = _unlockTime>block.timestamp?_unlockTime:block.timestamp;
        // calling with _unlockTime = 0 will set stored unlockTime = block.timestamp, so Collect will only succeed if
        // block.timestamp > stored unlockTime. To allow both outcomes, we don't constrain unlockOffset here.

        // Observe before values
        uint beforeContract = address(c).balance;
        (uint beforeUnlock, uint beforeHolder) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after values
        uint afterContract = address(c).balance;
        (uint afterUnlock, uint afterHolder) = c.Acc(address(this));

        // General rule:
        // If Collect succeeded (not reverted) then contract balance decreased by exactly collectAmount
        // and the reported holder balance decreased by at least collectAmount.
        // If Collect reverted then no guarantees are required by this property (allowed).
        assert(
            reverted || (afterContract + collectAmount == beforeContract && beforeHolder >= afterHolder && beforeHolder - afterHolder >= collectAmount)
        );
    }

    // Allow receiving Ether forwarded from C when Collect sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmount: amount to send in Put to deposit to this contract's holder record
    // collectAmount: amount to request via Collect
    // unlockOffset: seconds to add to block.timestamp for unlockTime passed to Put
    function run(uint putAmount, uint collectAmount, uint unlockOffset) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to forward");

        // Prepare by depositing funds to c for this contract's address
        uint unlockTime = block.timestamp + unlockOffset;
        c.Put{value: putAmount}(unlockTime);

        // Observe before-values
        uint beforeContract = address(c).balance;
        (, uint beforeHolder) = c.Acc(address(this));

        // Try Collect and record revert flag
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint afterContract = address(c).balance;
        (, uint afterHolder) = c.Acc(address(this));

        // General rule: If Collect succeeded then
        // 1) contract balance decreased by exactly collectAmount
        // 2) the reported holder balance decreased by exactly collectAmount
        // 3) beforeHolder equals the holder balance previously reflected in contract's balance for this address (we can only observe holder value), so enforce exact decrease equality
        assert(reverted || (afterContract + collectAmount == beforeContract && beforeHolder == afterHolder + collectAmount));
    }

    // Allow receiving Ether forwarded from C when Collect sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmount: amount to send in Put to deposit to this contract's holder record
    // collectAmount: amount to request via Collect
    // unlockOffset: seconds added to block.timestamp for unlockTime passed to Put
    function run(uint putAmount, uint collectAmount, uint unlockOffset) public payable {
        // need funds to forward to Put
        require(address(this).balance >= putAmount, "insufficient balance to forward");

        uint unlockTime = block.timestamp + unlockOffset;

        // deposit funds so this contract has a recorded holder balance in c
        c.Put{value: putAmount}(unlockTime);

        // read before-values via public getters
        uint beforeContractBalance = address(c).balance;
        (, uint beforeHolderBalance) = c.Acc(address(this));

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterContractBalance = address(c).balance;
        (, uint afterHolderBalance) = c.Acc(address(this));

        // General rule:
        // If Collect succeeded then the holder's recorded balance does not increase (afterHolder <= beforeHolder)
        // and the contract's ether balance does not increase (afterContract <= beforeContract).
        assert(reverted || (afterHolderBalance <= beforeHolderBalance && afterContractBalance <= beforeContractBalance));
    }

    // allow receiving Ether sent from C during Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call parameters: unlock time and amount to send to Put
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // observe contract balance and holder balance before the call
        uint balBefore = address(c).balance;
        // Acc is a public mapping to Holder; the getter returns (unlockTime, balance)
        (uint ubefore, uint holderBalBefore) = c.Acc(address(this));

        // perform Put with Ether amount
        c.Put{value: amount}(_unlockTime);

        // observe after
        uint balAfter = address(c).balance;
        (uint uafter, uint holderBalAfter) = c.Acc(address(this));

        // General invariant: contract balance increases by exactly the sent amount,
        // and the recorded holder balance does not decrease (it should be >= before).
        assert(balAfter == balBefore + amount && holderBalAfter >= holderBalBefore);
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

