contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to attempt to collect
    function run(uint _am) public payable {
        // No precondition on _am; ensure this test contract has some ETH to fund potential Put via fallback if needed.
        // Observe c's and this contract's view of holder before any action
        uint balBefore = address(c).balance;
        (uint unlockBefore, uint holderBalBefore) = c.Acc(address(this));

        // Try to call Collect and catch whether it reverted
        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint balAfter = address(c).balance;
        (uint unlockAfter, uint holderBalAfter) = c.Acc(address(this));

        // General rule:
        // - The holder's recorded balance must never increase as a result of Collect.
        // - If Collect succeeded (did not revert) then the contract's balance decreased by at most _am
        //   and the holder's recorded balance decreased by at most _am.
        // - If Collect reverted then balances are unchanged.
        assert(
            // holder balance never increases
            holderBalAfter <= holderBalBefore
            && (
                reverted
                ? (balAfter == balBefore && holderBalAfter == holderBalBefore)
                : (
                    // when not reverted, contract balance decrease equals holder decrease and both are <= _am
                    balBefore >= balAfter
                    && holderBalBefore >= holderBalAfter
                    && (balBefore - balAfter) <= _am
                    && (holderBalBefore - holderBalAfter) <= _am
                )
            )
        );
    }

    // allow receiving ETH if needed (not used in this test but present to accept refunds)
    receive() external payable {}
}

