contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to Collect `_am`. We require nothing about _am (can be any uint).
    // The test calls Collect and observes whether it reverted. If it succeeded,
    // then the reported stored balance for this contract (c.Acc(address(this)).balance)
    // must have decreased by exactly the amount transferred, and address(c).balance
    // must also have decreased by that same amount. If it reverted, no state change is required.
    function run(uint _am) public payable {
        // read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        // call Collect and catch revert
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If the call reverted, no guarantee about balances (other than no observable change here isn't required).
        // If it didn't revert, then the contract must have sent exactly `_am` to this caller,
        // meaning stored balance decreased by `_am` and contract balance decreased by `_am`.
        assert(reverted || (afterBalance + _am == beforeBalance && cBalAfter + _am == cBalBefore));
    }

