contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to Collect `_am`. We observe whether it reverts. If it does not revert,
    // then prior to the call the stored balance for this test contract must have been
    // >= c.MinSum() and >= _am and the stored unlockTime must have been < block.timestamp.
    function run(uint _am) public payable {
        // read pre-call observable state
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If Collect did not revert, then the contract's own stored balance before the call
        // must have been >= MinSum and >= _am, and its unlockTime must have been < block.timestamp.
        // (We use beforeUnlock and beforeBalance which were read before the call.)
        assert(reverted || (beforeBalance >= minSum && beforeBalance >= _am && beforeUnlock < block.timestamp));
    }

    receive() external payable {}
}

