        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterStoredBal) = c.Acc(address(this));

        // General property: if Collect did not revert, contract balance and stored balance
        // decreased by exactly _am, and unlockTime is unchanged for this holder.
        assert(reverted || (beforeContractBal == afterContractBal + _am
                            && beforeStoredBal == afterStoredBal + _am
                            && beforeUnlock == afterUnlock));
    }

    receive() external payable {}
}

