    // Test parameters: deposit amount to Put, unlock time to set so Collect can succeed, and collect amount
    function run(uint deposit, uint unlock, uint collectAmt) public payable {
        // we need funds to call Put
        require(address(this).balance >= deposit);

        // Make sure the account has deposit recorded: call Put sending deposit
        bool putReverted;
        try c.Put{value: deposit}(unlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe before-values for this test contract's holder and contract balance
