            collectReverted = true;
        }

        // Observe after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule:
        // If Collect succeeded (didn't revert) then contract balance decreased by exactly collectAmt
        // and the stored Acc balance for this address decreased by exactly collectAmt.
        // If Collect reverted then both the contract balance and stored balance remain unchanged.
        // Note: We allow Put to have reverted earlier; Collect's behavior is still characterized by the above.
        assert(
            (!collectReverted && afterContractBalance + collectAmt == beforeContractBalance && afterBal + collectAmt == beforeBal)
            || (collectReverted && afterContractBalance == beforeContractBalance && afterBal == beforeBal)
        );
    }

