        }

        // observe after-values
        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));

        // General rule:
        // If Put succeeded then contract balance increased by exactly deposit
        // and the recorded Acc.balance did not decrease (afterAccBal >= beforeAccBal).
        // If Put reverted then nothing observable changed.
        assert(
            (!putReverted && afterContractBal == beforeContractBal + deposit && afterAccBal >= beforeAccBal)
            || (putReverted && afterContractBal == beforeContractBal && afterAccBal == beforeAccBal)
        );
    }

    receive() external payable {}
