contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: call Put to deposit some ether for this contract's address (InvMutTest is msg.sender to c),
    // then call Collect attempting to withdraw some amount. We assert that if Collect did not revert,
    // then the public Acc(msg.sender).balance decreased by the withdrawn amount and the contract balance reflects at least that outflow.

    function run(uint putAmount, uint collectAmount, uint unlockTime, address payable /* unused */) public payable {
        // ensure we have enough balance to forward to Put
        require(address(this).balance >= putAmount, "insufficient test balance");
        // use our contract as the msg.sender to c by calling c from here

        // Read balance before any operations
        C.Holder memory beforeAcc = c.Acc(address(this));
        uint beforeHolderBal = beforeAcc.balance;
        uint beforeContractBal = address(c).balance;

        // Make a Put to deposit putAmount and set unlock time
        c.Put{value: putAmount}(unlockTime);

        // Read after put
        C.Holder memory afterPutAcc = c.Acc(address(this));
        uint afterPutHolderBal = afterPutAcc.balance;
        uint afterPutContractBal = address(c).balance;

        // Sanity: afterPutHolderBal should be beforeHolderBal + putAmount
        // (We don't assert here because Put could have other logic; we only use values later.)

        // Attempt to Collect collectAmount and catch whether it reverts
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after collect
        C.Holder memory afterCollectAcc = c.Acc(address(this));
        uint afterCollectHolderBal = afterCollectAcc.balance;
        uint afterCollectContractBal = address(c).balance;

        // If Collect did not revert, then holder balance must have decreased by exactly collectAmount,
        // and contract balance must have decreased by at least collectAmount (it may be equal or more if other state changed).
        // We express this as an implication: not reverted => (afterHolder = afterPutHolderBal - collectAmount && afterContractBal + collectAmount <= beforeContractBal + putAmount)
        // To avoid underflow in the assert we rearrange: afterPutHolderBal == afterCollectHolderBal + collectAmount
        // and afterCollectContractBal + collectAmount <= afterPutContractBal

        assert(reverted || (afterPutHolderBal == afterCollectHolderBal + collectAmount && afterCollectContractBal + collectAmount <= afterPutContractBal));
    }

    // Allow receiving Ether to fund put calls
    receive() external payable {}
}

