        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractEth = address(c).balance;

        // Fund c for this holder: call Put with preFund
        bool putReverted;
        try c.Put{value: preFund}(0) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after funding
        (uint afterFundUnlock, uint afterFundBalance) = c.Acc(address(this));
        uint afterFundContractEth = address(c).balance;

        // Now try Collect(amount)
        bool collectReverted;
        try c.Collect(amount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractEth = address(c).balance;

        // The general rule to assert:
        // If Collect reverted then recorded balance and contract Ether balance remain unchanged compared to just after funding;
