                : (
                    afterBalance + amount == afterFundBalance && // recorded balance decreased exactly by amount
                    afterContractEth + amount <= afterFundContractEth   // contract's ETH decreased by at least amount
                )
            )
        );
    }

    receive() external payable {}
}

