        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule:
        // - If Collect succeeded, then recorded balance decreased by exactly collectAmount
        //   and the contract's balance decreased by at least collectAmount (it could be more if Log contract forwarded etc.).
        // - If Collect reverted, then the recorded balance did not increase compared to before Collect (i.e., afterBalance <= midBalance)
        //   and the contract's balance did not increase compared to midContractBalance.
        assert(
            collectReverted
            ? (
                // when reverted: balances must not have increased (no accidental credit)
                afterBalance <= midBalance && afterContractBalance <= midContractBalance
              )
            : (
                // when succeeded: recorded decrease exactly collectAmount and contract balance decreased by at least collectAmount
                // avoid underflow in comparisons by using >= where appropriate
                midBalance >= collectAmount && afterBalance + collectAmount == midBalance && midContractBalance >= afterContractBalance && (midContractBalance - afterContractBalance) >= collectAmount
              )
        );
    }

    receive() external payable {}
}

